{"implementation": "def solve(case):
    if 'threshold' not in case:
        raise ValueError('Missing required field: threshold')
    if 'calls' not in case:
        raise ValueError('Missing required field: calls')
    threshold = case['threshold']
    calls = case['calls']
    if not isinstance(threshold, (int, float)) or isinstance(threshold, bool):
        raise ValueError('threshold must be a number')
    if not isinstance(calls, list):
        raise ValueError('calls must be a list')
    required_fields = {'call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable'}
    diagnostics = []
    accepted_call_ids = []
    for i, call in enumerate(calls):
        if not isinstance(call, dict):
            raise ValueError(f'Call at index {i} must be an object')
        missing = required_fields - set(call.keys())
        if missing:
            raise ValueError(f'Call at index {i} missing fields: {missing}')
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        prediction_tokens = call['prediction_tokens']
        parseable = call['parseable']
        if not isinstance(loss_without, (int, float)) or isinstance(loss_without, bool):
            raise ValueError(f'loss_without_call must be numeric for {call_id}')
        if not isinstance(loss_with, (int, float)) or isinstance(loss_with, bool):
            raise ValueError(f'loss_with_call must be numeric for {call_id}')
        if not isinstance(prediction_tokens, (int, float)) or isinstance(prediction_tokens, bool) or prediction_tokens < 1:
            raise ValueError(f'prediction_tokens must be >= 1 for {call_id}')
        if not isinstance(parseable, bool):
            raise ValueError(f'parseable must be boolean for {call_id}')
        gain = loss_without - loss_with
        normalized_gain = gain / prediction_tokens
        accepted = parseable and (normalized_gain >= threshold)
        normalized_gain_rounded = round(normalized_gain, 6)
        diagnostics.append({
            'call_id': call_id,
            'accepted': accepted,
            'normalized_gain': normalized_gain_rounded
        })
        if accepted:
            accepted_call_ids.append(call_id)
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"}
